const Serverless = require('./lib/Serverless');
const AwsProvider = require('./lib/plugins/aws/provider/awsProvider');
const AwsCompileStreamEvents = require('./lib/plugins/aws/package/compile/events/stream');

function runCase(roleValue, caseName) {
  const sls = new Serverless();
  sls.setProvider('aws', new AwsProvider(sls));
  // minimal compiled CF template with IamRoleLambdaExecution
  sls.service.provider.compiledCloudFormationTemplate = {
    Resources: {
      IamRoleLambdaExecution: {
        Properties: {
          Policies: [ { PolicyDocument: { Statement: [] } } ],
        },
      },
    },
    Outputs: {},
  };
  sls.service.service = 'test-svc';
  sls.service.provider.role = roleValue;
  sls.service.functions = {
    first: {
      handler: 'handler.hello',
      events: [ { stream: 'arn:aws:kinesis:region:account:stream/foo' } ],
    },
  };

  const plugin = new AwsCompileStreamEvents(sls);
  plugin.compileStreamEvents();
  const resources = sls.service.provider.compiledCloudFormationTemplate.Resources;
  const key = Object.keys(resources).find(k => k.includes('EventSourceMappingKinesis'));
  console.log(`Case ${caseName}: DependsOn =`, resources[key].DependsOn);
}

runCase('testKinesisStreamRoleLogicalId', 'logical-id');
runCase('arn:aws:iam::123456789012:role/foo', 'arn-role');

